import java.util.*;

class Solution {
    public List<List<String>> cardRangePart1(String BIN, List<List<String>> info) {
        String low = BIN + "0000000000", high = BIN + "9999999999";
        info.sort((a, b) -> (BIN + a.get(0)).compareTo(BIN + b.get(0)));
        List<List<String>> out = new ArrayList<>();
        for (List<String> iv : info) out.add(new ArrayList<>(List.of(BIN + iv.get(0), BIN + iv.get(1), iv.get(2))));
        if (out.isEmpty()) return out;
        out.get(0).set(0, low);
        out.get(out.size() - 1).set(1, high);
        return out;
    }
}

#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    vector<vector<string>> cardRangePart1(string BIN, vector<vector<string>>& info) {
        string low = BIN + string(10, '0'), high = BIN + string(10, '9');
        vector<vector<string>> ivs;
        for (auto& iv : info) ivs.push_back({BIN + iv[0], BIN + iv[1], iv[2]});
        sort(ivs.begin(), ivs.end());
        if (ivs.empty()) return ivs;
        ivs.front()[0] = low; ivs.back()[1] = high;
        return ivs;
    }
};
